// The Quiet Pantry — entry program (Node 22, standard library only).
// The game itself is the static game/ folder beside this file: plain HTML +
// ES modules a desktop browser loads fully offline. This program hands it in:
// it copies game/ and screenshots/ to the output directory and writes
// dossier.json there with the vendored make.fun library, so the judge's
// summary is generated by the kit's own code, byte for byte.
//
// Outside the grader's container, MAKEFUN_OUTPUT_DIR stands in for /output:
//   mkdir -p out && MAKEFUN_OUTPUT_DIR=out node main.ts

import { cpSync, existsSync, mkdirSync, readdirSync, statSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { buildDossier } from './vendor/makefun-game.ts';

const here = fileURLToPath(new URL('.', import.meta.url));
const out = process.env.MAKEFUN_OUTPUT_DIR ?? '/output';

mkdirSync(out, { recursive: true });
cpSync(join(here, 'game'), join(out, 'game'), { recursive: true });
mkdirSync(join(out, 'screenshots'), { recursive: true });
if (existsSync(join(here, 'screenshots'))) {
  cpSync(join(here, 'screenshots'), join(out, 'screenshots'), { recursive: true });
}

// Self-check before the dossier is built: walk the copied game/ tree and
// refuse loudly if it ever outgrows the scorer's caps, instead of handing in
// an entry the gate would reject on size alone.
function* walk(dir: string): Generator<string> {
  for (const name of readdirSync(dir)) {
    const p = join(dir, name);
    if (statSync(p).isDirectory()) yield* walk(p);
    else yield p;
  }
}
{
  let files = 0, bytes = 0;
  for (const f of walk(join(out, 'game'))) { files += 1; bytes += statSync(f).size; }
  if (files > 993 || bytes > 50331648) {
    throw new Error(`game/ over the scorer caps: ${files} files, ${bytes} bytes`);
  }
}

// The caps below are the scorer's own (from the kit): they refuse locally
// anything the scorer would refuse — more than 4 screenshots or one over
// 256 KiB, more than 993 files or 48 MiB under game/, or an over-long path.
writeFileSync(
  join(out, 'dossier.json'),
  buildDossier(out, {
    text_max_bytes: 163840,
    screenshots: { max: 4, max_bytes: 262144 },
    game_max_files: 993,
    game_max_bytes: 50331648,
    game_path_max_bytes: 1000,
  }),
);
